function aktualisiereLadebalken() {
  var aktuelleZeit = new Date().getTime();
  var wartezeit = startzeit + 1000; // 1 Sekunde Wartezeit
  if (aktuelleZeit < wartezeit) {
    setTimeout(aktualisiereLadebalken, 16); // 16ms = 60fps
